import type { AskFailureCode } from "@/lib/ai/client";

/** Shown under a rule-based answer to explain why Gemini did not answer. One entry per failure code. */
export const FALLBACK_NOTICES: Record<AskFailureCode, string> = {
  ai_not_configured:
    "Gemini is not configured on this server, so this answer was generated by BreatheWise's rule engine.",
  ai_timeout: "Gemini took too long to respond, so this answer comes from the rule engine.",
  ai_rate_limited:
    "Gemini's usage limit was reached for the moment, so this answer comes from the rule engine. Try again in a minute.",
  ai_unavailable: "Gemini is temporarily unavailable, so this answer comes from the rule engine.",
  ai_invalid_output:
    "Gemini's response failed BreatheWise's safety and accuracy checks and was discarded. This answer comes from the rule engine.",
  rate_limited: "Too many questions in a short time. This answer comes from the rule engine.",
  network: "The assistant service could not be reached. This answer comes from the rule engine.",
  invalid_request: "The question could not be sent to Gemini, so this answer comes from the rule engine.",
  forbidden_origin: "The question could not be sent to Gemini, so this answer comes from the rule engine.",
  payload_too_large:
    "The question was too large to send to Gemini, so this answer comes from the rule engine.",
  unsupported_media_type:
    "The question could not be sent to Gemini, so this answer comes from the rule engine.",
  unknown: "The AI response was unavailable, so this answer comes from the rule engine.",
};

export const AI_DISABLED_NOTICE = "AI is turned off in Settings. This answer comes from the rule engine.";

interface ModeInput {
  aiEnabled: boolean;
  /** null while the server's AI status is still being checked. */
  configured: boolean | null;
  hasData: boolean;
}

/** One-line status shown above the conversation: which engine will answer, and why. */
export function assistantModeLabel({ aiEnabled, configured, hasData }: ModeInput): string {
  if (!aiEnabled) return "Rule-based mode: AI is turned off in Settings";
  if (configured === null) return "Checking AI availability…";
  if (!configured) return "Rule-based mode: Gemini is not configured";
  return hasData ? "Gemini AI, grounded in your local data" : "Rule-based mode until a location is selected";
}
